namespace SpriteKind {
    export let PathEnd = SpriteKind.create()
    export let Cursor = SpriteKind.create()
    export let Tower = SpriteKind.create()
    export let ScreenText = SpriteKind.create()
    export let Inventory = SpriteKind.create()
    export let TowerImage = SpriteKind.create()
    export let Splash = SpriteKind.create()
}

// sprite initialization
let towerClone: Sprite = null
let enemySprite: Sprite = null
let cursor: Sprite = null
let target: Sprite = null
let textSprite: TextSprite = null

// inventory initialization
let towerImages = [assets.image`smallTowerImage`, assets.image`medTowerImage`, assets.image`largeTowerImage`]
let towerCosts = [100, 200, 300]
let inventoryOpen = false
let holdingTower = false

// game initialization
let gameWave = false
let enemyCount = 0
let enemyNum = 0
let enemyImages: Image[] = []
let gameWaveCount: number = null
let towerVelocity: number = null
let levelNum: number = null
let lives: number = null
let money: number = null
let levelStarted = false

// run game
callScene(0)

// game functions
function callSplash() {
    // background and title
    scene.setBackgroundImage(assets.image`splashBackground`)
    let splashText = sprites.create(assets.image`splashText`, SpriteKind.Splash)
    // turtle animation
    let turtleAnim = sprites.create(assets.image`splashTurtleImage`, SpriteKind.Splash)
    turtleAnim.setPosition(20, 70)
    animation.runImageAnimation(turtleAnim, assets.animation`splashAnimTurtle`, 500, true)
    // crab animation
    let crabAnim = sprites.create(assets.image`splashCrabImage`, SpriteKind.Splash)
    crabAnim.setPosition(140, 70)
    animation.runImageAnimation(crabAnim, assets.animation`splashAnimCrab`, 300, true)
}

function callMenu() {
    let levelSelectEasy = sprites.create(assets.image`levelSelectEasy`, SpriteKind.Splash)
    let levelSelectMed = sprites.create(assets.image`levelSelectMed`, SpriteKind.Splash)
    let levelSelectHard = sprites.create(assets.image`levelSelectHard`, SpriteKind.Splash)
    createTextSprite("Choose a path!", 1, 6, 8, 80, 15, null)
    createTextSprite("Easy", 1, 6, 5, 46, 64, null)
    createTextSprite("Medium", 1, 6, 5, 116, 64, null)
    createTextSprite("Hard", 1, 6, 5, 84, 108, null)
}

function callScene(sceneNum: number) {
    if (sceneNum == 0) { 
        // splash screen
        callSplash()
        sprites.destroyAllSpritesOfKind(SpriteKind.Splash)
        controller.pauseUntilAnyButtonIsPressed()
        story.printDialog("Defend the beach from the crabs by placing sandcastle towers along their path!", 80, 60, 40, 140, 8, 9)
        story.printDialog("Press B to open and close the inventory. Press A to select and place a tower.", 80, 60, 40, 140, 8, 9)
        story.printDialog("Earn points to buy new towers by eliminating the crabs in each wave!", 80, 60, 40, 140, 8, 9)
        callScene(1)
    } else if (sceneNum == 1) { 
        // level select menu
        callMenu()
        createCursor(assets.image`arrowCursor`)
        spriteutils.onSpriteKindUpdateInterval(SpriteKind.Splash, 100, function (sprite: Sprite) {
            if (cursor.overlapsWith(levelSelectEasy) && controller.A.isPressed()) {
                sprites.destroyAllSpritesOfKind(SpriteKind.Splash)
                sprites.destroyAllSpritesOfKind(SpriteKind.ScreenText)
                sprites.destroyAllSpritesOfKind(SpriteKind.Cursor)
                if (sprite.image.equals(assets.image`levelSelectEasy`)) {
                    callScene(2)
                }
                if (sprite.image.equals(assets.image`levelSelectEasy`)) {
                    callScene(3)
                }
                if (sprite.image.equals(assets.image`levelSelectHard`)) {
                    callScene(4)
                }
            }
        })

    } else if (sceneNum == 2) {
        tiles.setCurrentTilemap(assets.tilemap`easyLevel`)
        coverTiles()
        initializeLevel()
        levelNum = 1
    } else if (sceneNum == 3) {
        tiles.setCurrentTilemap(assets.tilemap`medLevel`)
        coverTiles()
        initializeLevel()
        levelNum = 2
    } else if (sceneNum == 4) {
        tiles.setCurrentTilemap(assets.tilemap`hardLevel`)
        coverTiles()
        initializeLevel()
        levelNum = 3
    } else if (sceneNum == 5) {
        // game over screen
        gameWave = false
        levelStarted = false
        sprites.destroyAllSpritesOfKind(SpriteKind.Enemy)
        sprites.destroyAllSpritesOfKind(SpriteKind.Tower)
        sprites.destroyAllSpritesOfKind(SpriteKind.PathEnd)
        sprites.destroyAllSpritesOfKind(SpriteKind.Cursor)
        sprites.destroyAllSpritesOfKind(SpriteKind.Projectile)
        sprites.destroyAllSpritesOfKind(SpriteKind.ScreenText)
        tileUtil.unloadTilemap()
        scene.setBackgroundImage(assets.image`splashBackground`)
        let gameOverText = sprites.create(assets.image`gameOverText`, SpriteKind.Splash)
        if (lives <= 0) {
            music.play(music.melodyPlayable(music.powerUp), music.PlaybackMode.InBackground)
        } else {
            music.play(music.melodyPlayable(music.powerDown), music.PlaybackMode.InBackground)
            effects.confetti.startScreenEffect()
        }
        timer.after(2000, function () {
            createTextSprite("Press any key", 8, 9, 8, 80, 104, null)
            createTextSprite("to play again!", 8, 9, 8, 80, 114, null)
            controller.pauseUntilAnyButtonIsPressed()
            sprites.destroyAllSpritesOfKind(SpriteKind.Splash)
            sprites.destroyAllSpritesOfKind(SpriteKind.ScreenText)
            effects.confetti.endScreenEffect()
            callScene(1)
        })
    }
}

scene.onHitWall(SpriteKind.Enemy, function (sprite: Sprite, location: tiles.Location) {
    if (tiles.tileAtLocationEquals(sprite.tilemapLocation(), assets.tile`rightArrow`)) {
        sprite.setVelocity(40, 0)
    } else if (tiles.tileAtLocationEquals(sprite.tilemapLocation(), assets.tile`downArrow`)) {
        sprite.setVelocity(0, 40)
    } else if (tiles.tileAtLocationEquals(sprite.tilemapLocation(), assets.tile`leftRightArrow`)) {
        if (Math.percentChance(50)) {
            sprite.setVelocity(-40, 0)
        } else {
            sprite.setVelocity(40, 0)
        }
    }
})

function coverTiles() {
    tileUtil.createSpritesOnTiles(assets.tile`endTile`, assets.image`pathEndImage`, SpriteKind.PathEnd)
    tileUtil.coverAllTiles(assets.tile`endTile`, assets.tile`sandTile`)
    tileUtil.coverAllTiles(assets.tile`rightArrow`, assets.tile`rightPathTile`)
    tileUtil.coverAllTiles(assets.tile`downArrow`, assets.tile`downPathTile`)
    tileUtil.coverAllTiles(assets.tile`leftRightArrow`, assets.tile`pathTile`)
}

function createCursor(image: Image) {
    cursor = sprites.create(image, SpriteKind.Cursor)
    cursor.z = 20
    controller.moveSprite(cursor)
    cursor.setFlag(SpriteFlag.GhostThroughWalls, true)
    cursor.setFlag(SpriteFlag.StayInScreen, true)
}

function initializeLevel() {
    createCursor(assets.image`arrowCursor`)
    gameWaveCount = 0
    lives = 20
    money = 300
    createScreenText()
    levelStarted = true
}

function createTextSprite(text: string, fgColor: number, bgColor: number, fontSize: number, xPos: number, yPos: number, icon: Image) {
    textSprite = textsprite.create(text, bgColor, fgColor)
    textSprite.setMaxFontHeight(fontSize)
    textSprite.setPosition(xPos, yPos)
    textSprite.setIcon(icon)
    textSprite.setKind(SpriteKind.ScreenText)
}

function createScreenText() {
    sprites.destroyAllSpritesOfKind(SpriteKind.ScreenText)
    createTextSprite(convertToText(lives), 1, 11, 8, 121, 4, assets.image`livesIcon`)
}

function callInventory(open: boolean) {
    if (open) {
        let inventoryRect = image.create(65, 120)
        let inventory = sprites.create(inventoryRect, SpriteKind.Inventory)
        inventoryRect.fill(8)
        inventoryRect.drawRect(0, 0, 65, 120, 1)
        inventoryRect.drawLine(5, 20, 60, 20, 1)
        inventory.setPosition(128, 60)
        createTextSprite("Inventory", 1, 0, 5, 129, 12, null)
        for (let i = 0; i <= towerImages.length - 1; i++) {
            let towerInventory = sprites.create(towerImages[i], SpriteKind.TowerImage)
            towerInventory.setPosition(110, 32 + i * 22)
            towerInventory.z = 10
        }
        for (let j = 0; j <= towerCosts.length - 1; j++) {
            createTextSprite(convertToText(towerCosts[j]), 1, 0, 8, 135, 32 + (j * 22), null)
        }
        createTextSprite(convertToText(gameWaveCount + 1), 1, 11, 8, 120, 90, assets.image`waveIcon`)
        createTextSprite(convertToText(money), 1, 11, 8, 120, 107, assets.image`moneyIcon`)
    } else if (!open) {
        sprites.destroyAllSpritesOfKind(SpriteKind.ScreenText)
        sprites.destroyAllSpritesOfKind(SpriteKind.Inventory)
        sprites.destroyAllSpritesOfKind(SpriteKind.TowerImage)
        createScreenText()
        if (cursor.image.equals(assets.image`squareCursor`)) {
            cursor.setImage(assets.image`arrowCursor`)
        }
    }
}

// game wave functions and events
function startWave(waveNum: number) {
    createTextSprite("Wave " + waveNum, 8, 9, 16, 80, 60, null)
    textSprite.lifespan = 1500
    music.play(music.createSong(assets.song`waveSong`), music.PlaybackMode.LoopingInBackground)
    gameWave = true
    enemyCount = 0
    if (waveNum == 1) {
        spawnEnemy(assets.image`redCrabImage`, 4)
    } else if (waveNum == 2) {
        spawnEnemy(assets.image`redCrabImage`, 8)
    } else if (waveNum == 3) {
        spawnEnemy(assets.image`redCrabImage`, 3)
        spawnEnemy(assets.image`blueCrabImage`, 3)
    } else if (waveNum == 4) {
        spawnEnemy(assets.image`redCrabImage`, 5)
        spawnEnemy(assets.image`blueCrabImage`, 5)
    } else if (waveNum == 5) {
        spawnEnemy(assets.image`redCrabImage`, 5)
        spawnEnemy(assets.image`blueCrabImage`, 4)
        spawnEnemy(assets.image`redCrabImage`, 5)
    } else if (waveNum == 6) {
        spawnEnemy(assets.image`redCrabImage`, 4)
        spawnEnemy(assets.image`blueCrabImage`, 4)
        spawnEnemy(assets.image`redCrabImage`, 4)
        spawnEnemy(assets.image`blueCrabImage`, 4)
    } else if (waveNum == 7) {
        spawnEnemy(assets.image`blueCrabImage`, 12)
    } else if (waveNum == 8) {
        spawnEnemy(assets.image`redCrabImage`, 5)
        spawnEnemy(assets.image`greenCrabImage`, 5)
        spawnEnemy(assets.image`redCrabImage`, 5)
    } else if (waveNum == 9) {
        spawnEnemy(assets.image`redCrabImage`, 5)
        spawnEnemy(assets.image`greenCrabImage`, 5)
        spawnEnemy(assets.image`blueCrabImage`, 5)
        spawnEnemy(assets.image`greenCrabImage`, 5)
        spawnEnemy(assets.image`redCrabImage`, 5)
    } else if (waveNum == 10) {
        spawnEnemy(assets.image`redCrabImage`, 5)
        spawnEnemy(assets.image`greenCrabImage`, 5)
        spawnEnemy(assets.image`redCrabImage`, 5)
        spawnEnemy(assets.image`blueCrabImage`, 5)
        spawnEnemy(assets.image`greenCrabImage`, 5)
        spawnEnemy(assets.image`redCrabImage`, 5)
    }
    enemyNum = enemyImages.length
}

function spawnEnemy(image: Image, num: number) {
    for (let count = 0; count < num; count++) {
        enemyImages.unshift(image)
    }
}

game.onUpdateInterval(1000, function () {
    if (gameWave && enemyCount < enemyNum) {
        enemyCount++
        enemySprite = sprites.create(enemyImages.removeAt(enemyImages.length - 1), SpriteKind.Enemy)
        if (levelNum == 1) {
            tiles.placeOnTile(enemySprite, tiles.getTileLocation(0, 3))
        } else if (levelNum == 2) {
            tiles.placeOnTile(enemySprite, tiles.getTileLocation(0, 2))
        } else if (levelNum == 3) {
            tiles.placeOnTile(enemySprite, tiles.getTileLocation(0, 1))
        }
        if (enemySprite.image.equals(assets.image`redCrabImage`)) {
            animation.runImageAnimation(enemySprite, assets.animation`redCrabAnim`, 200, true)
        } else if (enemySprite.image.equals(assets.image`blueCrabImage`)) {
            animation.runImageAnimation(enemySprite, assets.animation`blueCrabAnim`, 200, true)
        } else if (enemySprite.image.equals(assets.image`greenCrabImage`)) {
            animation.runImageAnimation(enemySprite, assets.animation`greenCrabAnim`, 200, true)
        }
        enemySprite.vx = 40
    }
})

scene.onOverlapTile(SpriteKind.Enemy, assets.tile`endTile`, function (sprite: Sprite, location: tiles.Location) {
    if (sprite.image.equals(assets.image`greenCrabImage`)) {
        sprites.destroy(sprite)
        lives -= 3
    } else if (sprite.image.equals(assets.image`blueCrabImage`)) {
        sprites.destroy(sprite)
        lives -= 2
    } else if (sprite.image.equals(assets.image`redCrabImage`)) {
        sprites.destroy(sprite)
        lives -= 1
    }
    createScreenText()
    if (lives <= 0) {
        callScene(5)
    }
})

game.onUpdate(function () {
    if (gameWave) {
        if (enemyCount == enemyNum && sprites.allOfKind(SpriteKind.Enemy).length == 0) {
            endWave()
        }
    }
})

function endWave() {
    if (gameWaveCount == 10) {
        callScene(5)
    } else {
        gameWave = false
        enemyImages = []
        music.stopAllSounds()
        createCursor(assets.image`arrowCursor`)
        tiles.setTileAt(tiles.getTileLocation(9, 0), assets.tile`playTile`)
        sprites.destroyAllSpritesOfKind(SpriteKind.Projectile)
    }
}

// inventory events
controller.B.onEvent(ControllerButtonEvent.Pressed, function () {
    if (levelStarted && !gameWave && !holdingTower) {
        if (inventoryOpen) {
            inventoryOpen = false
        } else {
            inventoryOpen = true
        }
        callInventory(inventoryOpen)
    }
})

sprites.onOverlap(SpriteKind.Cursor, SpriteKind.Inventory, function (sprite: Sprite, otherSprite: Sprite) {
    sprite.setImage(assets.image`arrowCursor`)
})

sprites.onOverlap(SpriteKind.Cursor, SpriteKind.TowerImage, function (sprite: Sprite, otherSprite: Sprite) {
    sprite.setImage(assets.image`squareCursor`)
    if (controller.A.isPressed()) {
        if (otherSprite.image.equals(assets.image`smallTowerImage`) && money >= 100) {
            sprite.setImage(otherSprite.image)
            money -= 100
        } else if (otherSprite.image.equals(assets.image`medTowerImage`) && money >= 200) {
            sprite.setImage(otherSprite.image)
            money -= 200
        } else if (otherSprite.image.equals(assets.image`largeTowerImage`) && money >= 300) {
            sprite.setImage(otherSprite.image)
            money -= 300
        }
        holdingTower = true
        inventoryOpen = false
        callInventory(inventoryOpen)
    }
})

// gameplay events
controller.A.onEvent(ControllerButtonEvent.Pressed, function () {
    if (levelStarted) {
        if (cursor.tileKindAt(TileDirection.Center, assets.tile`sandTile`) && (cursor.image.equals(assets.image`smallTowerImage`) || cursor.image.equals(assets.image`medTowerImage`) || cursor.image.equals(assets.image`largeTowerImage`))) {
            towerClone = sprites.create(cursor.image, SpriteKind.Tower)
            tiles.placeOnTile(towerClone, tiles.getTileLocation(cursor.tilemapLocation().column, cursor.tilemapLocation().row))
            tiles.setTileAt(tiles.getTileLocation(cursor.tilemapLocation().column, cursor.tilemapLocation().row), assets.tile`sandTileCover`)
            cursor.setImage(assets.image`arrowCursor`)
            holdingTower = false
        }
    }
})

scene.onOverlapTile(SpriteKind.Cursor, assets.tile`playTile`, function (sprite: Sprite, location: tiles.Location) {
    if (controller.A.isPressed()) {
        sprites.destroy(sprite)
        tiles.setTileAt(location, assets.tile`runningTile`)
        gameWaveCount++
        startWave(gameWaveCount)
    }
})

spriteutils.onSpriteKindUpdateInterval(SpriteKind.Tower, 750, function(sprite: Sprite) {
    if (gameWave) {
        if (sprite.image.equals(assets.image`smallTowerImage`)) {
            target = spriteutils.getSpritesWithin(SpriteKind.Enemy, 25, sprite)._pickRandom()
            towerVelocity = 25
        } else if (sprite.image.equals(assets.image`medTowerImage`)) {
            target = spriteutils.getSpritesWithin(SpriteKind.Enemy, 35, sprite)._pickRandom()
            towerVelocity = 40
        } else if (sprite.image.equals(assets.image`largeTowerImage`)) {
            target = spriteutils.getSpritesWithin(SpriteKind.Enemy, 45, sprite)._pickRandom()
            towerVelocity = 60
        }
        if (target) {
            let projectile = sprites.createProjectileFromSprite(assets.image`projectileImage`, sprite, 0, 0)
            spriteutils.setVelocityAtAngle(projectile, spriteutils.angleFrom(sprite, target), towerVelocity)
            projectile.setFlag(SpriteFlag.GhostThroughWalls, true)
        }
    }
})

sprites.onOverlap(SpriteKind.Projectile, SpriteKind.Enemy, function(sprite: Sprite, otherSprite: Sprite) {
    if (otherSprite.image.equals(assets.image`redCrabImage`)) {
        sprites.destroy(sprite)
        sprites.destroy(otherSprite)
        money += 10
    } else if (otherSprite.image.equals(assets.image`blueCrabImage`)) {
        sprites.destroy(sprite)
        otherSprite.setImage(assets.image`redCrabImage`)
        animation.runImageAnimation(otherSprite, assets.animation`redCrabAnim`, 500, true)
        money += 10
    } else if (otherSprite.image.equals(assets.image`greenCrabImage`)) {
        sprites.destroy(sprite)
        otherSprite.setImage(assets.image`blueCrabImage`)
        animation.runImageAnimation(otherSprite, assets.animation`blueCrabAnim`, 500, true)
        money += 10
    }
    createScreenText()
    music.play(music.melodyPlayable(music.pewPew), music.PlaybackMode.UntilDone)
})

